import json
from pathlib import Path
root=Path(__file__).resolve().parents[1] / 'schemas'
root.mkdir(exist_ok=True)
def obj(props, required, extra=True):return {"type":"object","properties":props,"required":required,"additionalProperties":extra}
def st(v=None):return {"type":"string",**({"enum":v} if v else {})}
def arr(x):return {"type":"array","items":x}
strs=st()
pred=obj({"path":strs,"op":st(["eq","ne","ge","le","contains","set_eq","exists","absent"]),"value":{}},["path","op"])
obl=obj({"id":strs,"kind":st(["READ","ANALYZE","COMMUNICATE","WAIT","WRITE","REFUSE","RECONCILE"]),"agent_id":strs,"tool":strs,"required_targets":arr(strs),"depends_on":arr(strs),"trigger":obj({"event_id":strs,"match":obj({},[])},["event_id"]),"evidence_predicates":arr(pred),"recipient":strs,"deadline":{"type":"number"},"not_before":{"type":"number"},"min_count":{"type":"integer","minimum":1}},["id","kind","agent_id"])
mission=obj({"schema_version":st(["legion.mission.v1"]),"mission_id":strs,"scenario_id":strs,"source_family":st(["SCALE_DAG","GAIA2_STRUCTURAL","OTEL_STRUCTURAL","ADVERSARIAL"]),"source_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"objective":st(["completion","refusal"]),"goal_predicates":arr(pred),"obligations":arr(obl),"required_agents":arr(strs),"require_provider_for_all_roles":{"type":"boolean"},"require_claims":{"type":"boolean"},"budgets":obj({"max_events":{"type":"integer","minimum":1},"max_duration":{"type":"number","exclusiveMinimum":0}},[])},["schema_version","mission_id","scenario_id","source_family","source_sha256","objective","goal_predicates","obligations"])
reg=obj({"campaign_id":strs,"mission_id":strs,"scenario_id":strs,"source_family":strs,"attempt_index":{"const":1},"frozen_before_execution":{"const":True},"eligible":{"type":"boolean"},"invalid_policy":st(["count_as_nonpass","exclude_preregistered"]),"split":strs},["campaign_id","mission_id","scenario_id","source_family","attempt_index","frozen_before_execution","eligible","invalid_policy"])
event=obj({"id":strs,"kind":st(["MODEL_DECISION","GOVERNANCE","COMMIT","NATIVE_EFFECT","RECEIPT","READBACK_EFFECT","OBSERVATION","ANALYSIS_RECORD","MESSAGE_DELIVERED","WAIT_OBSERVED","DENIAL","RECONCILE","ENV_EVENT","RUN_STOPPED","CLAIM"]),"origin":strs,"t":{"type":"number","minimum":0},"agent_id":strs,"obligation_id":strs},["id","kind","origin","t"])
evidence=obj({"mission_id":strs,"scenario_id":strs,"clock_kind":st(["monotonic_single_host"]),"trace_complete":{"type":"boolean"},"readback_origin":strs,"final_native_state":{"type":"object"},"events":arr(event),"semantic_disputes":arr(strs)},["mission_id","scenario_id","clock_kind","trace_complete","readback_origin","final_native_state","events"])
check=obj({"check_id":strs,"status":st(["PASS","FAIL","INDETERMINATE","SAFE_STOP","INVALID_TEST"]),"reason_code":strs,"evidence_refs":arr(strs)},["check_id","status","reason_code","evidence_refs"])
verdict=obj({"schema_version":st(["legion.oracle.verdict.v1"]),"oracle_build":strs,"mission_id":{"type":["string","null"]},"scenario_id":strs,"campaign_id":strs,"attempt_index":{"type":["integer","null"]},"verdict":st(["PASS","FAIL","SAFE_STOP","INDETERMINATE","INVALID_TEST"]),"mandatory_checks":arr(check),"completion_witness_sha256":{"type":["string","null"]},"check_families":{"type":"object"},"test_posture":arr(strs)},["schema_version","oracle_build","verdict","mandatory_checks","completion_witness_sha256"])
cohort=obj({"schema_version":st(["legion.cohort.v1"]),"invalid_policy":st(["count_as_nonpass","exclude_preregistered"]),"missions":arr(obj({"mission_id":strs,"scenario_id":strs,"eligible":{"type":"boolean"},"invalid_disposition":st(["EXCLUDE","COUNT"])},["mission_id","scenario_id","eligible"]))},["schema_version","invalid_policy","missions"])
for name,data in [("mission.schema.json",mission),("registration.schema.json",reg),("evidence.schema.json",evidence),("verdict.schema.json",verdict),("cohort.schema.json",cohort)]:
 data={"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"urn:legion100:judge:schema:"+name,"title":name,"description":"Legion v0.1 synthetic evaluator schema, not a live attestation",**data}
 (root/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
